                  '这个设计带来三个推论。**第一,它是逻辑复制而非物理复制**——从库的表结构、索引甚至存储引擎都可以与主库不同,只要逻辑上能重放。好处是灵活,坏处是「从库可能比主库慢」:主库走索引的更新,从库缺索引就要全表扫。',
                  '**第二,从库只做重放,不做决策**——它不优化、不改写,只是照着执行。所以主库上一条高效语句,到了从库不一定高效;主库上一条低效语句,到了从库同样低效,而且会堵住后面所有语句。',
                  '**第三,为什么需要 `relay log`**——它把「搬运」和「执行」解耦了。搬运线程可以快速把日志取回本地,哪怕执行线程一时跟不上;如果中途断开,已取回的部分不用重新拉。理解这一点,就理解了「为什么会有两个位点」,也就理解了延迟诊断为什么必须看两段。',
