                      '写入路径是：**命令 → `aof_buf`（Redis 进程内的 SDS 缓冲区）→ 内核页缓存（`write` 系统调用）→ 磁盘（`fsync`）**。**三段都可能丢数据**：`aof_buf` 还没 `write` 时宕机 → 丢；`write` 了但没 `fsync`，机器断电 → 丢（数据在内核页缓存里）；`fsync` 成功 → 安全。**三种策略就是在这三层之间取舍**。**顺带解释「为什么 AOF 文件比 RDB 大」**：AOF 存的是「所有历史命令」，一个被反复 `INCR` 的计数器会留下 10 万条记录，而 RDB 只存最终值 `100000`——**这就是需要「AOF 重写」的根本原因**。',
