                caption:
                  '**「AOF 重写是读取旧 AOF 文件来压缩吗」——不是，这是最常见的误解**。重写**根本不读旧 AOF**，而是**直接遍历当前内存**生成命令——因为「内存里的当前状态」本身就包含了「所有历史命令的最终效果」，**从状态反推最小命令集，天然去掉所有冗余**。**举例**：`INCR k` 执行了 10 万次，旧 AOF 有 10 万行，重写后只有一行 `SET k 100000`；一个 `LPUSH` 了 1000 次的 List，重写后是一条批量 `RPUSH` 命令。**这个「从状态重建最小等价日志」的思想，与数据库的「逻辑备份」、Kafka 的「日志压缩（log compaction）」完全一致。**',
