                title: 'AOF 日志是怎么实现的？为什么是写后日志？三种刷盘策略？',
                questionId: 'java-07-Q27',
                intent:
                  '写后日志的三笔账（不阻塞、免校验、不记垃圾）+ 两个风险 + 三档策略。',
                points: [
                  '**写后日志**：**先内存执行 → 成功后再追加到 `aof_buf` → 按策略刷盘**',
                  '**三笔账**：不阻塞当前命令、**不需要预校验命令合法性**、不会记录执行失败的垃圾',
                  '**对比 redo log（写前日志）**：redo 是物理日志，必须先写日志再改页（WAL）；**AOF 是逻辑日志，重放即重新执行，所以能后写**',
                  '**风险一**：执行成功但写 AOF 前宕机 → 丢这条命令（`always` 可缓解）',
                  '**风险二**：写 AOF 失败（磁盘满）→ 内存与磁盘不一致，Redis 拒绝后续写（`aof_last_write_status`）',
                  '**三档**：`always`（丢 0 条、吞吐掉到几千）/ `everysec`（**默认**，丢 ~1 秒）/ `no`（丢 ~30 秒，由内核决定）',
                ],
                depth:
                  '**「写后日志」与「写前日志」的选择依据要讲透**：**日志的用途决定了写入顺序**。**redo log 用于「崩溃恢复一个可能只改了一半的页」**，所以必须在改页之前落盘，否则页被改坏而日志没有记录；**AOF 用于「从零重建整个数据集」**，重放的是**完整命令**，所以「先执行还是先记录」不影响正确性——只影响「丢多少」与「能不能预校验」。**更进一步**：写前日志需要「校验命令合法性」——如果记录了非法命令，恢复时会在中途失败，整个数据集不可用；**写后日志天然不会记录失败的命令**，恢复一定成功。**这个「日志类型 → 写入顺序 → 校验需求」的推导链，是这道题最深的层次。**',
                followup:
                  '「`everysec` 真的只丢 1 秒吗」——**理论上是，但有边界**：如果「上次 `fsync` 还没完成」，主线程会被阻塞等待，此时延迟上升但**不会多丢**；而**机器断电**时，内核页缓存里最多 1 秒的数据丢失。**但云主机的「宿主机断电」** 可能让磁盘缓存里的数据也丢（write cache 未刷）——**所以「1 秒」是 Redis 层的最坏值，实际取决于存储链路**。这一点能主动提，会显得你真的踩过坑。',
