                caption:
                  '**回答 Q34 的高分句式**：「**Redis 主从是异步复制，只能保证最终一致，不能保证强一致**——因为主节点写入 `replication buffer` 就返回成功，不等从节点确认。**这带来两个后果**：**主节点宕机可能丢「已确认但未同步」的数据；从节点可能读到旧数据**。**能做的事有三层**：**监控延迟（offset 差）、用 `WAIT` 对关键写做有限等待、对一致性敏感的读强制走主**。**想真正强一致就不该用 Redis 做主存储**——这是选型问题，不是配置问题。」**这个回答的价值在于「划清能力边界」，而不是硬拗「Redis 也能强一致」。**',
