                  '**脑裂的准确含义**：主节点与「哨兵 + 从节点」之间网络断开，但**主节点与部分客户端仍连通**。此时**哨兵判定主节点客观下线并选出新主**，而**旧主仍在接受客户端写入**——于是出现「两个主节点同时存在」，这就是脑裂。**丢数据的机制**：旧主在隔离期间写的命令**没有同步到任何从节点**；等网络恢复，哨兵把旧主降为从节点，**旧主必须先清空自己的数据、从新主做全量同步**（因为它与新主的数据已经分叉，无法用增量对齐）——**那批「只在旧主上存在」的写入就此消失**。',
