                depth:
                  '**「全量同步为什么要有 `replication buffer`」**——因为 `bgsave` 期间主节点仍在接受写，这些写在 RDB 里没有。**如果没有这个缓冲**，从节点加载完 RDB 就是「fork 时刻的状态」，**之后的写全丢**。**这个缓冲是「每个从节点一个」**（不是共享），所以**从节点越多，主节点内存开销越大**——这也是「不要挂太多从节点」的原因（一般建议单主 ≤ 5 个从节点，更多用级联）。**追问「`repl_backlog` 和 `replication buffer` 有什么区别」**——**前者是「全局共享的环形历史缓冲」，用于「断线重连后补发」**；**后者是「每个从节点一个的发送队列」，用于「实时推送」**。两个缓冲各管一段场景，容易混。',
