                depth:
                  '**「`WAIT` 能保证一致吗」——不能，要说清它的三个边界**：**① 只保证「命令到达从节点的内存缓冲」，不保证「已执行」**；**② 超时后照样返回**（返回「实际确认的从节点数」），所以调用方要自己判断返回值；**③ 它阻塞的是「当前客户端」**，不影响其他客户端——所以它不能替代「全局一致」。**`WAIT` 的正确用途是「关键写的兜底」**：如下单后 `WAIT 1 100`，如果返回 0 说明「至少 100ms 内没有从节点确认」，可以主动降级或记录补偿。**能讲清「它的保证范围」，比说「用 WAIT 保证一致」专业得多。**',
