                  '**缓存穿透**：**请求的数据在缓存和数据库里都不存在**。比如「查一个不存在的用户 ID」，缓存必然未命中 → 每次都打到数据库 → 数据库被大量「注定查不到」的请求压垮。**关键特征是「数据不存在」**，所以**缓存也救不了**（因为没东西可缓存）。**典型场景**：恶意攻击（用随机 ID 刷接口）、业务 bug（用错误的 ID 查询）、爬虫遍历。**缓存击穿**：**某个热点 key 过期的瞬间**，大量并发请求同时未命中 → 一起打到数据库 → 数据库瞬间被这一个 key 的查询压垮。**关键特征是「数据存在，但缓存刚失效」**，所以**问题是「并发重建」而不是「数据不存在」**。**缓存雪崩**：**大量 key 在同一时间集中失效**（或缓存实例整体不可用）→ 大量请求同时打到数据库 → 数据库被压垮。**关键特征是「面」而不是「点」**——击穿是「一个热点 key」，雪崩是「一大片 key 或整个缓存层」。',
