                  '**三种典型成因**：**① 大量 key 同时过期**——最常见。典型错误是「批量预热时给所有 key 设同一个 TTL」（如凌晨 2 点全量刷新，TTL 都设 24 小时）→ **第二天凌晨 2 点集体过期** → 所有请求同时回源。**② 缓存实例整体不可用**——单节点 Redis 挂了、或主从切换期间（几十秒不可写）→ 全部请求回源。**③ 冷启动**——服务刚上线/重启、或缓存被清空 → 缓存命中率 0，**全部流量直接压到数据库**。',
                  '**对应的四层解法（要按「事前 → 事中 → 事后」组织）**：**事前**——**① TTL 加随机值**（如 `base + random(0, 300)` 秒），把「同时过期」打散成「均匀过期」；**② 多级缓存**（本地缓存 + Redis），Redis 挂了还有本地挡一层；**③ 缓存预热**（启动/大促前主动加载热点）。**事中**——**④ 熔断限流**：当数据库压力达到阈值时，**主动拒绝部分请求**（返回降级内容），**保住数据库不被打死**——**这是最关键的一层，因为前三层都只能「降低概率」，不能「保证不发生」**。**事后**——**⑤ 降级兜底**（返回默认值/缓存快照/静态页）+ **快速恢复**（Redis 集群高可用、持久化恢复）。',
