                      '**三个理由**：**① 更新缓存可能是「无效写」**——如果这个 key 写完之后**根本没人读**（写多读少的场景），更新缓存就是纯浪费（还占了内存，可能挤掉热数据）。**删除是「懒加载」**：等真的有人读时再回填，**只缓存「被读过的东西」**。**② 并发更新会导致「旧值覆盖新值」**——两个线程同时更新同一个 key，**数据库的更新顺序是 A→B，但「更新缓存」的顺序可能是 B→A**，于是缓存里留下了 A 的旧值，且**会一直错到下次过期**。**删除则没有顺序问题**（删两次结果一样）。**③ 更新缓存的「值」可能很贵**——如果缓存里存的是「聚合结果」（如「商品 + 库存 + 促销」，要查三个服务），**每次写都要重算一遍**；删除只要一次 `DEL`。**所以结论是「删除优于更新」，这是 Cache Aside 的标准做法**。',
