                  '「逻辑过期怎么实现才不重复重建」——**用一把「重建锁」（`SETNX` 短 TTL）**：谁抢到谁去异步重建，**其余线程直接返回旧值不等**。**注意「重建失败」的处理**：如果重建线程查库失败，**不要删除旧值**（否则下次请求会 miss 并再次触发重建，形成雪崩），**应该保留旧值并记录告警**，等下次再试。**这个「保留旧值」的细节是逻辑过期的关键**——它的设计哲学是「宁可给旧值，也不给空」。',
