                depth:
                  '**「为什么熔断限流是核心」要讲透**：**雪崩的杀伤力来自「数据库被打死」**，而**数据库一旦被打死，恢复要几分钟到几十分钟**（连接堆积、慢查询排队、主从延迟拉大、甚至需要重启）。**限流的作用是「有损服务」**——**牺牲 30% 请求（返回降级页），保住 70% 正常**；**不 limit 则 100% 都超时**。**这个「有损优于全损」的判断是可用性设计的核心**，与「舱壁隔离」「超时控制」「重试退避」是一套方法论。**面试里如果只答「TTL 加随机」，会被认为只懂皮毛**——**因为 TTL 随机只能「降低同时过期的概率」，挡不住「Redis 整体挂了」和「冷启动」**。',
                followup:
                  '「多级缓存怎么保证一致性」——**用「广播失效」+「短 TTL」双保险**：Redis 侧数据变更时，**通过 `Pub/Sub` 或 MQ 广播「删本地 key」**，各实例收到后删自己的本地缓存；**同时本地缓存设短 TTL（如 5 秒）**，**兜住「广播丢失」的情况**。**所以本地缓存 TTL = 「可接受的最长不一致时间」**，想更一致就得广播更可靠（如改成「版本号轮询」）。**这也是「本地缓存不能存「强一致数据」」的原因**——它天生就是「最终一致」的。',
