                intent:
                  '五种模式（Cache Aside / Read-Through / Write-Through / Write-Behind / Write-Around）+ 为什么旁路最常用。',
                points: [
                  '**Cache Aside（旁路）**：读 miss 回填；写**先更新库再删缓存**；**控制权在业务层，最灵活、容错最好**',
                  '**Read/Write Through**：缓存层代理数据库读写，**业务代码极简但要中间件支持**',
                  '**Write Behind**：只写缓存、**异步批量落库**；写性能极高但**可能丢数据**',
                  '**Write Around**：写只落库不碰缓存，**实现最简单但陈旧时间长**',
                  '**为什么 Cache Aside 是默认**：**Redis 是旁路组件**（不侵入业务）、**缓存故障时业务仍可走库**、实现成本最低',
                  '**代价**：一致性由业务保证（有窗口）、每个查询都要写「读缓存→回源→回填」',
                ],
                depth:
                  '**「Spring Cache 的 `@Cacheable` 属于哪种」**——**它本质是 Read-Through 的简化版**（方法级：miss 时执行方法并回填），**写侧用 `@CacheEvict` 就是 Cache Aside 的「删缓存」**。**注意 `@CacheEvict` 的坑**：**它默认在方法执行「之后」删**（`beforeInvocation = false`），这与「先更新库再删缓存」一致；**但如果方法抛异常，缓存不会被删**（因为根本没执行到）。**另一个坑是「事务与缓存」**：`@CacheEvict` 在方法返回时就删了，**但如果外层事务还没提交（`@Transactional` 提交在方法之后）**，此时「删缓存 → 事务提交」之间有窗口，**并发读会把旧值回填**——**正确做法是「事务提交后再删」（用 `TransactionSynchronizationManager` 的 `afterCommit`）**。**这个坑非常真实，能说出来是实打实的经验。**',
                followup:
                  '「Write Behind 什么时候能用」——**只在「能接受丢数据」的场景**：**阅读数、点赞数、播放量、日志统计**。**实现要点**：**① 缓存里维护「脏 key 集合」**（或直接用 `Redis Stream` 记录变更），**② 后台线程定期批量刷库**（如每 100ms 或攒够 100 条），**③ 落库失败要重试 + 告警**。**绝对不能用它的场景**：订单、支付、库存——**这些丢了就是资损。**',
