                  '**第二层：binlog 订阅（Canal）**——伪装成 MySQL 从库解析 binlog，**按变更异步删缓存**',
                  '**Canal 的三个优势**：**不依赖应用代码**、**覆盖所有写入路径**（含人工改库）、**天然有序**',
