                  '**过期删除（expiration）**：**触发条件是「时间」**——key 设了 TTL，到点就该被清理。**它是「清理已到期的垃圾」，即使内存很空也会发生**（因为「过期」本身就意味着不该再被读到）。**内存淘汰（eviction）**：**触发条件是「内存压力」**——`used_memory` 超过 `maxmemory` 时，按策略**牺牲一些 key 来腾空间**。**它淘汰的可能是「完全没过期、还很热」的 key**（如果策略选到了它）。**两者的关系**：**过期删除会「顺带」释放内存**（所以如果过期删除足够及时，可能根本不会触发淘汰）；**但淘汰是「最后手段」**，它不看 TTL（除了 `volatile-ttl` 策略），只看策略。',
