                  '**这个「第三方」必须具备两个条件**：**① 所有参与者都能访问**（所以是「中心化」的）；**② 它的操作是原子的**（所以不能是「读一下再写一下」）。**Redis 和 ZooKeeper 都满足这两条**——Redis 靠单线程保证单命令原子，ZK 靠 ZAB 协议与节点版本号。**理解了这一点，就能明白「为什么自己用 MySQL 建一张锁表也能做分布式锁」**（靠 `INSERT` 唯一索引或 `SELECT ... FOR UPDATE`）——**只是性能差、还容易死锁**。',
