                solution: `public class SimpleRedisLock {
    private final Jedis jedis;

    /** ① 加锁：一条 SET NX PX，value 唯一标识持有者 */
    public boolean tryLock(String key, String owner, long ttlMillis) {
        String r = jedis.set(key, owner, SetParams.setParams().nx().px(ttlMillis));
        return "OK".equals(r);
    }

    /** ② 解锁：Lua 保证「比较 + 删除」原子，避免误删别人的锁 */
    private static final String UNLOCK_LUA =
        "if redis.call('get', KEYS[1]) == ARGV[1] then return redis.call('del', KEYS[1]) else return 0 end";

    public boolean unlock(String key, String owner) {
        Object r = jedis.eval(UNLOCK_LUA, 1, key, owner);
        return Long.valueOf(1).equals(r);
    }

    /** ③ 可重入：Hash 存「持有者 -> 次数」，field 不存在则计数 1，存在则 +1 */
    private static final String LOCK_LUA =
        "if redis.call('exists', KEYS[1]) == 0 then " +
        "  redis.call('hset', KEYS[1], ARGV[1], 1); " +
        "  redis.call('pexpire', KEYS[1], ARGV[2]); " +
        "  return 1 " +
        "end " +
        "if redis.call('hexists', KEYS[1], ARGV[1]) == 1 then " +
        "  redis.call('hincrby', KEYS[1], ARGV[1], 1); " +
        "  redis.call('pexpire', KEYS[1], ARGV[2]); " +
        "  return 1 " +
        "end " +
        "return 0";

    public boolean tryLockReentrant(String key, String owner, long ttlMillis) {
        Object r = jedis.eval(LOCK_LUA, 1, key, owner, String.valueOf(ttlMillis));
        return Long.valueOf(1).equals(r);
    }

    private static final String UNLOCK_REENTRANT_LUA =
        "if redis.call('hexists', KEYS[1], ARGV[1]) == 0 then return -1 end " +
        "local cnt = redis.call('hincrby', KEYS[1], ARGV[1], -1); " +
        "if cnt > 0 then redis.call('pexpire', KEYS[1], ARGV[2]); return cnt end " +
        "return redis.call('del', KEYS[1])";

    public boolean unlockReentrant(String key, String owner, long ttlMillis) {
        Object r = jedis.eval(UNLOCK_REENTRANT_LUA, 1, key, owner, String.valueOf(ttlMillis));
        return !Long.valueOf(-1).equals(r);
    }

    /** ④ 续期（看门狗）：只在「锁仍归自己」时重置 TTL */
    private static final String RENEW_LUA =
        "if redis.call('hexists', KEYS[1], ARGV[1]) == 1 then " +
        "  return redis.call('pexpire', KEYS[1], ARGV[2]) else return 0 end";

    public boolean renew(String key, String owner, long ttlMillis) {
        Object r = jedis.eval(RENEW_LUA, 1, key, owner, String.valueOf(ttlMillis));
        return Long.valueOf(1).equals(r);
    }
}`,
