                depth:
                  '**「为什么 `UNLINK` 能解决阻塞」要说清机制**：**`DEL` 是「从字典摘除 + `free` 所有元素」**，**后者是 O(N) 且在主线程**；**`UNLINK` 只做「摘除」（O(1)）**，**把「释放」放进 `lazy_free` 的后台队列**，**由 BIO 线程异步完成**。**所以「key 立刻不可见，但内存稍后才降」**。**追问「`UNLINK` 有没有上限」**——**有**，**后台释放队列也有大小限制**（`lazyfree-lazy-eviction` / `lazyfree-lazy-expire` / `lazyfree-lazy-server-del` 控制哪些场景自动用惰性释放），**如果短时间 `UNLINK` 大量大 key，队列会堆积，内存下降慢**。**但「主线程不阻塞」这个目标已经达成**。',
                followup:
                  '「大 key 在 Cluster 里为什么更危险」——**因为「一个 key 只能在一个槽、一个节点」**，**大 key 的读写压力无法通过加节点分摊**（**除非拆分 key 本身**）；**且迁移槽时「大 key 会被整体序列化传输」**，**可能造成秒级卡顿**。**所以 Cluster 对「大 key 治理」的要求比单机更高**——**这也是「线上 Cluster 集群必须定期跑 `--bigkeys`」的原因。**',
