                depth:
                  '**「无 ACK 怎么补救」是一条实用追问**：**用 `Stream` 代替 `ZSet`**——**`XADD` 时把「执行时间」放进字段，消费端轮询 `XREAD` 判断时间是否到，处理完 `XACK`**，**配合 `XPENDING` + `XAUTOCLAIM` 处理「消费者崩溃」**（**超时未 ACK 的消息可以转给其他消费者**）。**代价是「`Stream` 没有「按时间排序取出」的能力」**，**要自己过滤**（**所以「精确延迟」仍用 `ZSet`，「可靠投递」用 `Stream`**）。**另一个方案是「Redis + MQ 的组合」**：**`ZSet` 做「定时触发」，到点后把消息投给 MQ，由 MQ 保证可靠投递**——**这是生产上最常见的折中。**',
