                  '「轮询间隔怎么定」——**精度与开销的权衡**：**间隔 1 秒 → 延迟最多 1 秒，但每秒一次查询开销小；间隔 100ms → 精度更高，开销 10 倍**。**实践**：**「1 秒轮询 + 批量取 100 条」**通常够用；**要求秒级以内精度的场景应该用「时间轮」或「MQ 延迟消息」（如 RocketMQ 的 18 级时间轮）**。**注意「多实例轮询会导致重复取」**——**所以「取 + 删」必须原子（Lua），或者用「分布式锁 + 单实例消费」。**',
