                  '**成因**：**jemalloc 按 size class 分配**（申请 100 字节给 112 字节）+ **频繁增删导致空闲块不连续** + **大 key 删除后留下空洞**',
                  '**处理一**：**`activedefrag yes`**（4.0+，**后台整理，用 CPU 换内存**，配 `active-defrag-threshold-lower/upper`）',
